import sys
names, balances = [], []
def account(name):
    if name not in names:
        names.append(name)
        balances.append(0)
    return names.index(name)
for line in sys.stdin:
    p = line.split()
    if not p:
        continue
    if p[0] == 'BALANCE':
        print(balances[names.index(p[1])] if p[1] in names else 'ERROR')
    elif p[0] == 'INCOME':
        rate = int(p[1])
        for i in range(len(names)):
            if balances[i] > 0:
                balances[i] += balances[i] * rate // 100
    elif p[0] == 'TRANSFER':
        i, j = account(p[1]), account(p[2])
        balances[i] -= int(p[3])
        balances[j] += int(p[3])
    else:
        i = account(p[1])
        balances[i] += int(p[2]) * (1 if p[0] == 'DEPOSIT' else -1)
